import React, { useState } from 'react';
import { Cpu, FileText, GitBranch, ShieldCheck, RefreshCw, History, BarChart2 } from 'lucide-react';
import { useNavigate } from 'react-router-dom';

const CommandDock = ({ onSelectModule }) => {
  const [activeModule, setActiveModule] = useState('aicore');
  const navigate = useNavigate();

  const dockItems = [
    { id: 'aicore', name: 'AI Core', icon: Cpu },
    { id: 'resume', name: 'Resume Engine', icon: FileText },
    { id: 'github', name: 'GitHub Scanner', icon: GitBranch },
    { id: 'trust', name: 'Trust Core', icon: ShieldCheck },
    { id: 'skillswap', name: 'SkillSwap', icon: RefreshCw },
    { id: 'history', name: 'Analysis Logs', icon: History, action: () => navigate('/history') },
    { id: 'analytics', name: 'Metrics', icon: BarChart2 },
  ];

  const handleClick = (item) => {
    setActiveModule(item.id);
    if (item.action) {
      item.action();
    } else if (onSelectModule) {
      onSelectModule(item.id);
    }
  };

  return (
    <div className="fixed bottom-5 left-1/2 -translate-x-1/2 z-50">
      <div className="glass-card px-3 py-2 rounded-2xl border border-scifi-600/30 shadow-2xl backdrop-blur-2xl flex items-center space-x-1.5 sm:space-x-2">
        {dockItems.map((item) => {
          const Icon = item.icon;
          const isActive = activeModule === item.id;
          return (
            <button
              key={item.id}
              onClick={() => handleClick(item)}
              className={`relative p-2.5 rounded-xl transition-all duration-300 group flex flex-col items-center justify-center ${
                isActive
                  ? 'bg-scifi-600/40 text-scifi-100 border border-scifi-600/60 shadow-purple-glow scale-105'
                  : 'text-scifi-200 hover:text-scifi-100 hover:bg-white/5 hover:scale-105'
              }`}
              title={item.name}
            >
              <Icon className={`w-4 h-4 ${isActive ? 'text-scifi-100 animate-pulse' : 'text-scifi-200'}`} />
              <span className="absolute -top-8 px-2 py-0.5 rounded text-[10px] font-mono bg-scifi-950 text-scifi-100 border border-scifi-600/30 opacity-0 group-hover:opacity-100 transition-opacity pointer-events-none whitespace-nowrap shadow-lg">
                {item.name}
              </span>
              {isActive && (
                <span className="w-1 h-1 rounded-full bg-scifi-100 absolute -bottom-1 shadow-purple-glow" />
              )}
            </button>
          );
        })}
      </div>
    </div>
  );
};

export default CommandDock;
