import React, { useEffect, useRef } from 'react';

const GiganticHolographicEarth = () => {
  const canvasRef = useRef(null);

  useEffect(() => {
    const canvas = canvasRef.current;
    if (!canvas) return;
    const ctx = canvas.getContext('2d');

    let animationFrameId;
    let width = (canvas.width = canvas.parentElement.clientWidth || 700);
    let height = (canvas.height = canvas.parentElement.clientHeight || 700);

    const handleResize = () => {
      if (canvas.parentElement) {
        width = canvas.width = canvas.parentElement.clientWidth;
        height = canvas.height = canvas.parentElement.clientHeight;
      }
    };
    window.addEventListener('resize', handleResize);

    // Mouse movement state for 3D tilt reaction
    let mouseX = 0;
    let mouseY = 0;
    const handleMouseMove = (e) => {
      const rect = canvas.getBoundingClientRect();
      mouseX = ((e.clientX - rect.left) / rect.width - 0.5) * 0.5;
      mouseY = ((e.clientY - rect.top) / rect.height - 0.5) * 0.5;
    };
    window.addEventListener('mousemove', handleMouseMove);

    let rotationAngle = 0;
    const globeRadius = Math.min(width, height) * 0.44; // Gigantic Core

    // Continent Lat/Lng Coordinates
    const continents = [
      // North America
      { lat: 0.7, lng: -1.7 }, { lat: 0.8, lng: -1.9 }, { lat: 0.6, lng: -1.5 }, { lat: 0.5, lng: -1.4 }, { lat: 0.75, lng: -1.3 },
      // Europe
      { lat: 0.9, lng: 0.2 }, { lat: 0.8, lng: 0.3 }, { lat: 0.95, lng: 0.4 }, { lat: 0.85, lng: 0.1 }, { lat: 0.75, lng: 0.45 },
      // Asia
      { lat: 0.6, lng: 1.8 }, { lat: 0.7, lng: 2.1 }, { lat: 0.5, lng: 1.5 }, { lat: 0.4, lng: 2.3 }, { lat: 0.65, lng: 2.5 },
      // South America
      { lat: -0.2, lng: -1.0 }, { lat: -0.4, lng: -1.1 }, { lat: -0.6, lng: -0.9 },
      // Africa
      { lat: 0.1, lng: 0.3 }, { lat: -0.3, lng: 0.4 }, { lat: 0.3, lng: 0.5 }, { lat: -0.5, lng: 0.45 },
      // Australia
      { lat: -0.5, lng: 2.3 }, { lat: -0.4, lng: 2.5 }, { lat: -0.6, lng: 2.4 }
    ];

    const landPoints = continents.map(c => ({
      x: globeRadius * Math.cos(c.lat) * Math.cos(c.lng),
      y: globeRadius * Math.sin(c.lat),
      z: globeRadius * Math.cos(c.lat) * Math.sin(c.lng),
    }));

    // Latitude & Longitude Mesh Grid
    const meshPoints = [];
    const latLines = 18;
    const lngLines = 26;

    for (let i = 0; i <= latLines; i++) {
      const lat = (Math.PI * i) / latLines - Math.PI / 2;
      for (let j = 0; j < lngLines; j++) {
        const lng = (2 * Math.PI * j) / lngLines;
        meshPoints.push({
          x: globeRadius * Math.cos(lat) * Math.cos(lng),
          y: globeRadius * Math.sin(lat),
          z: globeRadius * Math.cos(lat) * Math.sin(lng),
        });
      }
    }

    // Active AI Nodes & Traveling Data Packets
    const activeNodes = [
      { name: 'GitHub Sync Node', lat: 0.7, lng: -1.7 },
      { name: 'Resume Parser', lat: 0.8, lng: 0.3 },
      { name: 'Trust Engine Radar', lat: 0.6, lng: 1.8 },
      { name: 'SkillSwap Pairing', lat: -0.4, lng: 2.3 },
    ];

    // Data packets traveling between nodes
    let packetProgress = 0;
    let pulseTime = 0;

    const render = () => {
      ctx.clearRect(0, 0, width, height);

      const centerX = width / 2;
      const centerY = height / 2;
      rotationAngle += 0.003; // Realistic slow rotation
      pulseTime += 0.025;
      packetProgress = (packetProgress + 0.008) % 1;

      // 1. Draw Deep Volumetric Atmospheric Purple Halo
      const bgGlow = ctx.createRadialGradient(centerX, centerY, globeRadius * 0.7, centerX, centerY, globeRadius * 1.35);
      bgGlow.addColorStop(0, 'rgba(99, 89, 133, 0.28)');
      bgGlow.addColorStop(0.6, 'rgba(68, 60, 104, 0.12)');
      bgGlow.addColorStop(1, 'rgba(24, 18, 43, 0)');

      ctx.beginPath();
      ctx.arc(centerX, centerY, globeRadius * 1.35, 0, Math.PI * 2);
      ctx.fillStyle = bgGlow;
      ctx.fill();

      // 2. Draw Dark Metallic Globe Sphere Base
      ctx.beginPath();
      ctx.arc(centerX, centerY, globeRadius - 2, 0, Math.PI * 2);
      ctx.fillStyle = '#0F0A1C';
      ctx.fill();

      // 3. Draw Outer Orbit Rings with Satellites
      ctx.save();
      ctx.translate(centerX, centerY);
      ctx.rotate(mouseY * 0.2);

      // Primary Orbital Ring
      ctx.beginPath();
      ctx.ellipse(0, 0, globeRadius * 1.42, globeRadius * 0.46, Math.PI / 6, 0, Math.PI * 2);
      ctx.strokeStyle = '#635985';
      ctx.lineWidth = 1.5;
      ctx.globalAlpha = 0.4;
      ctx.stroke();

      // Orbiting Satellite 1
      const satAngle1 = rotationAngle * 1.8;
      const sat1X = Math.cos(satAngle1) * globeRadius * 1.42;
      const sat1Y = Math.sin(satAngle1) * globeRadius * 0.46;
      ctx.beginPath();
      ctx.arc(sat1X, sat1Y, 3.5, 0, Math.PI * 2);
      ctx.fillStyle = '#EFEBF8';
      ctx.globalAlpha = 0.9;
      ctx.fill();

      // Secondary Counter Orbital Ring
      ctx.beginPath();
      ctx.ellipse(0, 0, globeRadius * 1.22, globeRadius * 0.38, -Math.PI / 3, 0, Math.PI * 2);
      ctx.strokeStyle = '#443C68';
      ctx.lineWidth = 1.2;
      ctx.globalAlpha = 0.35;
      ctx.stroke();

      ctx.restore();

      // 4. Project 3D Mesh Points with Cursor Reaction
      const cos = Math.cos(rotationAngle + mouseX * 0.3);
      const sin = Math.sin(rotationAngle + mouseX * 0.3);

      meshPoints.forEach((p) => {
        const rx = p.x * cos - p.z * sin;
        const rz = p.x * sin + p.z * cos;
        const scale = 500 / (500 + rz);

        if (rz < 60) {
          ctx.beginPath();
          ctx.arc(centerX + rx * scale, centerY + p.y * scale, 1.2 * scale, 0, Math.PI * 2);
          ctx.fillStyle = '#635985';
          ctx.globalAlpha = Math.max(0.08, (1 - rz / 280) * 0.32);
          ctx.fill();
        }
      });

      // 5. Project Deep Purple Illuminated Continents
      landPoints.forEach((p) => {
        const rx = p.x * cos - p.z * sin;
        const rz = p.x * sin + p.z * cos;
        const scale = 500 / (500 + rz);

        if (rz < 80) {
          ctx.beginPath();
          ctx.arc(centerX + rx * scale, centerY + p.y * scale, 2.8 * scale, 0, Math.PI * 2);
          ctx.fillStyle = '#9B8CBF';
          ctx.globalAlpha = Math.max(0.2, (1 - rz / 280) * 0.85);
          ctx.fill();
        }
      });

      // 6. Active Holographic AI Nodes & Connection Packets
      const projectedNodes = activeNodes.map((node) => {
        const nx = globeRadius * Math.cos(node.lat) * Math.cos(node.lng);
        const ny = globeRadius * Math.sin(node.lat);
        const nz = globeRadius * Math.cos(node.lat) * Math.sin(node.lng);

        const rx = nx * cos - nz * sin;
        const rz = nx * sin + nz * cos;
        const scale = 500 / (500 + rz);

        return {
          px: centerX + rx * scale,
          py: centerY + ny * scale,
          rz,
          scale,
        };
      });

      // Draw Connection Beams between Nodes
      for (let i = 0; i < projectedNodes.length - 1; i++) {
        const n1 = projectedNodes[i];
        const n2 = projectedNodes[i + 1];

        if (n1.rz < 80 && n2.rz < 80) {
          ctx.beginPath();
          ctx.moveTo(n1.px, n1.py);
          ctx.lineTo(n2.px, n2.py);
          ctx.strokeStyle = '#635985';
          ctx.lineWidth = 1;
          ctx.globalAlpha = 0.3;
          ctx.stroke();

          // Traveling Data Packet along Beam
          const packetX = n1.px + (n2.px - n1.px) * packetProgress;
          const packetY = n1.py + (n2.py - n1.py) * packetProgress;
          ctx.beginPath();
          ctx.arc(packetX, packetY, 2.5, 0, Math.PI * 2);
          ctx.fillStyle = '#EFEBF8';
          ctx.globalAlpha = 0.85;
          ctx.fill();
        }
      }

      // Draw Node Pulse Rings
      projectedNodes.forEach((n) => {
        if (n.rz < 90) {
          const pulseR = (Math.sin(pulseTime * 1.5) + 1) * 7 + 4;
          ctx.beginPath();
          ctx.arc(n.px, n.py, pulseR, 0, Math.PI * 2);
          ctx.strokeStyle = '#9B8CBF';
          ctx.lineWidth = 1;
          ctx.globalAlpha = 0.5;
          ctx.stroke();

          ctx.beginPath();
          ctx.arc(n.px, n.py, 4.5, 0, Math.PI * 2);
          ctx.fillStyle = '#EFEBF8';
          ctx.globalAlpha = 0.95;
          ctx.fill();
        }
      });

      animationFrameId = requestAnimationFrame(render);
    };

    render();

    return () => {
      window.removeEventListener('resize', handleResize);
      window.removeEventListener('mousemove', handleMouseMove);
      cancelAnimationFrame(animationFrameId);
    };
  }, []);

  return (
    <div className="w-full h-full min-h-[440px] sm:min-h-[580px] lg:min-h-[640px] relative flex items-center justify-center">
      <canvas ref={canvasRef} className="w-full h-full max-w-[700px] max-h-[700px]" />
    </div>
  );
};

export default GiganticHolographicEarth;
